"SELECT DISTINCT\nA.[CLAIM_ID],\nCOALESCE(C.[Updated Timeliness SLA Result(Dispute Log)],A.[Encounter Submitted Timely])          AS \"Updated Encounter Timeliness SLA Result\",\nCOALESCE(C.[Updated Acceptance SLA Result(Dispute Log)],B.[Encounter MAO002 Status])             AS \"Updated Encounter Acceptance SLA Result\"\n\n\nFROM [Encounter SLA Calculation] AS A\nLEFT JOIN [Encounter MAO002 Information] AS B ON A.[CLAIM_ID] = B.[CLAIM_ID]\nLEFT JOIN [Encounters SLA Dispute Log] AS C ON A.[CLAIM_ID] = C.[Claim ID]"
